head.b:skin:
/* --------------------------------------------------------------------------
 * EditorialVocab Blogger Theme CSS - Slate Dark & Modern Layout
 * -------------------------------------------------------------------------- */
:root {
  --bg-main: #0b0f19;
  --bg-card: #131b2e;
  --bg-card-hover: #1c2742;
  --border-color: #1e293b;
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --accent-indigo: #6366f1;
  --accent-purple: #a855f7;
  --accent-emerald: #10b981;
  --accent-amber: #f59e0b;
  --font-hindi: 'Hind', sans-serif;
  --font-body: 'Plus Jakarta Sans', sans-serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
body { background-color: var(--bg-main); color: var(--text-main); font-family: var(--font-body); line-height: 1.6; min-height: 100vh; }
a { color: var(--accent-indigo); text-decoration: none; transition: color 0.2s ease; }
a:hover { color: var(--accent-purple); }

/* Top Sticky Navigation Bar */
.site-navbar { background: rgba(19, 27, 46, 0.95); backdrop-filter: blur(12px); border-bottom: 1px solid var(--border-color); position: sticky; top: 0; z-index: 100; padding: 12px 20px; }
.nav-container { max-width: 1200px; margin: 0 auto; display: flex; align-items: center; justify-content: space-between; gap: 16px; }
.brand-logo { display: flex; align-items: center; gap: 10px; font-weight: 800; font-size: 20px; color: #fff; }
.brand-logo span { background: linear-gradient(135deg, var(--accent-indigo), var(--accent-purple)); padding: 4px 12px; border-radius: 8px; font-size: 14px; text-transform: uppercase; }
.nav-links { display: flex; gap: 20px; list-style: none; }
.nav-links a { color: var(--text-muted); font-size: 14px; font-weight: 700; }
.nav-links a:hover { color: #fff; }

/* Hero Banner Badge */
.site-hero { background: linear-gradient(135deg, #1e1b4b 0%, #0f172a 100%); border-bottom: 1px solid var(--border-color); padding: 40px 20px; text-anchor: middle; text-align: center; }
.hero-title { font-size: 32px; font-weight: 800; background: linear-gradient(to right, #fff, #a5f3fc); -webkit-background-clip: text; -webkit-text-fill-color: transparent; margin-bottom: 8px; }
.hero-sub { font-size: 16px; color: var(--text-muted); max-width: 680px; margin: 0 auto; }
.exam-badges { display: flex; justify-content: center; gap: 10px; margin-top: 16px; flex-wrap: wrap; }
.badge-pill { background: rgba(99, 102, 241, 0.15); border: 1px solid rgba(99, 102, 241, 0.3); color: #a5f3fc; font-size: 12px; font-weight: 700; padding: 4px 12px; border-radius: 20px; }

/* Main Grid Layout */
.main-layout { max-width: 1200px; margin: 30px auto; padding: 0 20px; display: grid; grid-template-columns: 1fr 340px; gap: 30px; }
.content-area { min-width: 0; }
.sidebar-area { min-width: 0; }

/* Post Card Item */
.post-card-item { background: var(--bg-card); border: 1px solid var(--border-color); border-radius: 16px; padding: 24px; margin-bottom: 24px; transition: transform 0.2s ease, border-color 0.2s ease; }
.post-card-item:hover { border-color: var(--accent-indigo); transform: translateY(-2px); }
.post-card-title { font-size: 24px; font-weight: 800; margin-bottom: 10px; line-height: 1.3; }
.post-card-title a { color: #fff; }
.post-meta { font-size: 13px; color: var(--text-muted); display: flex; gap: 12px; margin-bottom: 16px; }

/* Sidebar Widget */
.widget-box { background: var(--bg-card); border: 1px solid var(--border-color); border-radius: 16px; padding: 20px; margin-bottom: 24px; }
.widget-title { font-size: 16px; font-weight: 800; border-bottom: 2px solid var(--accent-indigo); padding-bottom: 8px; margin-bottom: 16px; color: #fff; text-transform: uppercase; letter-spacing: 0.5px; }

/* Footer Navigation Pages Bar */
.site-footer { background: #090d16; border-top: 1px solid var(--border-color); padding: 40px 20px; margin-top: 60px; text-align: center; }
.footer-pages-nav { display: flex; justify-content: center; gap: 20px; margin-bottom: 20px; flex-wrap: wrap; }
.footer-pages-nav a { color: var(--text-muted); font-size: 14px; font-weight: 600; }
.footer-pages-nav a:hover { color: var(--accent-emerald); }
.copyright-text { font-size: 13px; color: #64748b; }

/* Responsive Mobile Media Queries */
@media (max-width: 900px) {
  .main-layout { grid-template-columns: 1fr; }
  .hero-title { font-size: 24px; }
  .nav-links { display: none; }
}
